import{_ as a,o as t,c as o,a5 as l}from"./chunks/framework.DOB-AMqW.js";const h=JSON.parse('{"title":"Spendzo Data Collection","description":"Standalone data-collection disclosure for the Spendzo application.","frontmatter":{"title":"Spendzo Data Collection","description":"Standalone data-collection disclosure for the Spendzo application.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/spendzo.md","filePath":"data-collection/spendzo.md"}'),n={name:"data-collection/spendzo.md"};function i(s,e,r,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="spendzo-data-collection" tabindex="-1">Spendzo Data Collection <a class="header-anchor" href="#spendzo-data-collection" aria-label="Permalink to &quot;Spendzo Data Collection&quot;">​</a></h1><p><strong>Last Updated:</strong> July 30, 2026</p><h2 id="data-entered-and-stored-locally" tabindex="-1">Data entered and stored locally <a class="header-anchor" href="#data-entered-and-stored-locally" aria-label="Permalink to &quot;Data entered and stored locally&quot;">​</a></h2><p>Spendzo stores the financial and preference information you enter, including expenses, income, budgets, categories, notes, payment methods, tags, and security settings. This information stays in the app&#39;s private local database.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>The developer does not collect:</p><ul><li>Financial information entered in Spendzo</li><li>Personal details or account information</li><li>Device identifiers</li><li>App activity, diagnostics, or analytics</li><li>Location, contacts, photos, audio, or messages</li></ul><p>Spendzo has no account system, advertisements, trackers, or cloud sync. It does not send or share your data with third parties.</p><h2 id="optional-local-features" tabindex="-1">Optional local features <a class="header-anchor" href="#optional-local-features" aria-label="Permalink to &quot;Optional local features&quot;">​</a></h2><p>Fingerprint unlock is processed by Android; Spendzo does not receive biometric templates. Backup, CSV, and PDF files are created locally only when you request them and are saved to a location you choose.</p><p>For questions, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',11)])])}const u=a(n,[["render",i]]);export{h as __pageData,u as default};
